        require(amounts.length == tokens.length, "Array length mismatch");
        require(amounts.length <= MAX_BATCH_SIZE, "Batch too large");

        // Emergency mode: only allow essential operations
        if (emergencyMode) {
            _executeEmergencyMode(amounts, tokens);
            return;
        }

        uint256 successCount = 0;
        uint256 failureCount = 0;

        for (uint256 i = 0; i < amounts.length; i++) {
            try this._safeProcessToken(tokens[i], amounts[i]) {
                successCount++;

                // Optional features with graceful degradation
                if (rewardsEnabled) {
                    try this._safeUpdateRewards(tokens[i], amounts[i]) {
                        // Rewards updated successfully
                    } catch {
                        // Continue without rewards if system is stressed
                        emit RewardUpdateFailed(tokens[i], amounts[i]);
                    }
                }

                if (externalNotificationsEnabled) {
                    try this._safeNotifyExternal(tokens[i], amounts[i]) {
                        // Notification sent successfully
                    } catch {
                        // Continue without external notifications
                        emit ExternalNotificationFailed(tokens[i], amounts[i]);
                    }
                }

            } catch Error(string memory reason) {
                failureCount++;
                emit OperationFailed(tokens[i], amounts[i], reason);

                // If failure rate is too high, enable emergency mode
                if (failureCount * 100 / (successCount + failureCount) > FAILURE_THRESHOLD) {
                    emergencyMode = true;
                    emit EmergencyModeActivated("High failure rate detected");
                    break;
                }
            }
        }

        emit BatchProcessed(successCount, failureCount);

        // Require at least some operations to succeed
        require(successCount > 0, "All operations failed");
    }

    function _executeEmergencyMode(uint256[] memory amounts, address[] memory tokens) private {
        // In emergency mode, only process essential operations with strict limits
        uint256 processedCount = 0;

        for (uint256 i = 0; i < amounts.length && processedCount < EMERGENCY_BATCH_LIMIT; i++) {
            if (amounts[i] <= EMERGENCY_AMOUNT_LIMIT) {
                try this._safeProcessToken(tokens[i], amounts[i]) {
                    processedCount++;
                } catch {
                    // Skip failed operations in emergency mode
                    continue;
                }
            }
        }

        emit EmergencyBatchProcessed(processedCount);
    }
}
