// SECURE - Safe cross-contract dependency management
contract SecureSystem {
    struct Dependency {
        address contractAddress;
        bool isActive;
        uint256 lastHealthCheck;
        uint256 failureCount;
    }

    mapping(string => Dependency) public dependencies;
    mapping(string => address[]) public backupContracts;

    uint256 private constant MAX_FAILURES = 3;
    uint256 private constant HEALTH_CHECK_INTERVAL = 1 hours;

    event DependencyFailed(string name, address contractAddr, string reason);
    event DependencyRestored(string name, address contractAddr);
    event FallbackActivated(string name, address backupAddr);

    function initializeDependencies() external onlyOwner {
        _addDependency("priceOracle", 0x123..., true);
        _addDependency("liquidityProvider", 0x456..., true);

        // Add backup contracts
        backupContracts["priceOracle"].push(0x789...);
        backupContracts["liquidityProvider"].push(0xABC...);
    }

    function executeOperation(uint256 amount) external {
        uint256 price = _getPriceWithFallback();
        require(price > 0, "Unable to get valid price");

        bool liquidityProvided = _provideLiquidityWithFallback(amount * price);
        require(liquidityProvided, "Liquidity provision failed");

        emit OperationExecuted(amount, price);
    }

    function _getPriceWithFallback() internal returns (uint256) {
        Dependency storage oracle = dependencies["priceOracle"];

        if (oracle.isActive && _isHealthy("priceOracle")) {
            try IPriceOracle(oracle.contractAddress).getPrice() returns (uint256 price) {
                if (price > 0) {
                    _recordSuccess("priceOracle");
                    return price;
                }
            } catch Error(string memory reason) {
                _recordFailure("priceOracle", reason);
            }
        }

        // Try backup contracts
        address[] memory backups = backupContracts["priceOracle"];
        for (uint256 i = 0; i < backups.length; i++) {
            try IPriceOracle(backups[i]).getPrice() returns (uint256 price) {
                if (price > 0) {
                    emit FallbackActivated("priceOracle", backups[i]);
                    return price;
                }
            } catch {
                continue;
            }
        }

        return 0; // All sources failed
    }

    function _provideLiquidityWithFallback(uint256 value) internal returns (bool) {
        Dependency storage provider = dependencies["liquidityProvider"];

        if (provider.isActive && _isHealthy("liquidityProvider")) {
            try ILiquidityProvider(provider.contractAddress).provideLiquidity(value) {
                _recordSuccess("liquidityProvider");
                return true;
            } catch Error(string memory reason) {
                _recordFailure("liquidityProvider", reason);
            }
        }

        // Try backup contracts
        address[] memory backups = backupContracts["liquidityProvider"];
        for (uint256 i = 0; i < backups.length; i++) {
            try ILiquidityProvider(backups[i]).provideLiquidity(value) {
                emit FallbackActivated("liquidityProvider", backups[i]);
                return true;
            } catch {
                continue;
            }
        }

        return false; // All sources failed
    }

    function _isHealthy(string memory name) internal view returns (bool) {
        Dependency storage dep = dependencies[name];
        return dep.failureCount < MAX_FAILURES && 
               block.timestamp - dep.lastHealthCheck < HEALTH_CHECK_INTERVAL;
    }

    function _recordSuccess(string memory name) internal {
        Dependency storage dep = dependencies[name];
        if (dep.failureCount > 0) {
            dep.failureCount = 0;
            emit DependencyRestored(name, dep.contractAddress);
        }
        dep.lastHealthCheck = block.timestamp;
    }

    function _recordFailure(string memory name, string memory reason) internal {
        Dependency storage dep = dependencies[name];
        dep.failureCount++;

        if (dep.failureCount >= MAX_FAILURES) {
            dep.isActive = false;
        }

        emit DependencyFailed(name, dep.contractAddress, reason);
    }

    function _addDependency(string memory name, address addr, bool active) internal {
        dependencies[name] = Dependency({
            contractAddress: addr,
            isActive: active,
            lastHealthCheck: block.timestamp,
            failureCount: 0
        });
    }
}
