contract SecureIntegration {
    enum ProtocolVersion { V2, V3, V4 }

    struct ProtocolInfo {
        ProtocolVersion version;
        address routerAddress;
        bool isActive;
        uint256 minVersion;
        uint256 maxVersion;
    }

    mapping(string => ProtocolInfo) public protocols;
    mapping(string => mapping(ProtocolVersion => address)) public adapters;

    event ProtocolVersionUpdated(string protocol, ProtocolVersion newVersion);
    event AdapterDeployed(string protocol, ProtocolVersion version, address adapter);

    function initializeProtocols() external onlyOwner {
        // Initialize Uniswap with version detection
        protocols["uniswap"] = ProtocolInfo({
            version: ProtocolVersion.V3,
            routerAddress: 0x123...,
            isActive: true,
            minVersion: 2,
            maxVersion: 4
        });

        // Set up version-specific adapters
        adapters["uniswap"][ProtocolVersion.V2] = address(new UniswapV2Adapter());
        adapters["uniswap"][ProtocolVersion.V3] = address(new UniswapV3Adapter());
    }

    function swapOnUniswap(address token, uint256 amount) external {
        ProtocolInfo storage info = protocols["uniswap"];
        require(info.isActive, "Uniswap integration disabled");

        address adapter = adapters["uniswap"][info.version];
        require(adapter != address(0), "No adapter for current version");

        // Verify protocol version compatibility
        uint256 protocolVersion = _getProtocolVersion(info.routerAddress);
        require(
            protocolVersion >= info.minVersion && protocolVersion <= info.maxVersion,
            "Protocol version not supported"
        );

        // Use version-specific adapter
        ISwapAdapter(adapter).executeSwap(
            info.routerAddress,
            token,
            amount,
            msg.sender
        );

        emit SwapExecuted("uniswap", info.version, token, amount);
    }

    function updateProtocolVersion(
        string memory protocol,
        ProtocolVersion newVersion,
        address newRouter
    ) external onlyOwner {
        require(adapters[protocol][newVersion] != address(0), "Adapter not available");

        ProtocolInfo storage info = protocols[protocol];

        // Verify new version compatibility
        uint256 routerVersion = _getProtocolVersion(newRouter);
        require(
            routerVersion >= info.minVersion && routerVersion <= info.maxVersion,
            "New version not compatible"
        );

        info.version = newVersion;
        info.routerAddress = newRouter;

        emit ProtocolVersionUpdated(protocol, newVersion);
    }

    function _getProtocolVersion(address router) internal view returns (uint256) {
        // Try to detect version through interface support
        try IVersioned(router).version() returns (uint256 version) {
            return version;
        } catch {
            // Fallback version detection
            if (_supportsInterface(router, type(IUniswapV3Router).interfaceId)) {
                return 3;
            } else if (_supportsInterface(router, type(IUniswapV2Router).interfaceId)) {
                return 2;
            }
            return 0; // Unknown version
        }
    }

    function _supportsInterface(address contract_, bytes4 interfaceId) internal view returns (bool) {
        try IERC165(contract_).supportsInterface(interfaceId) returns (bool supported) {
            return supported;
        } catch {
            return false;
        }
    }

    // Emergency function to disable problematic protocol versions
    function disableProtocol(string memory protocol) external onlyOwner {
        protocols[protocol].isActive = false;
        emit ProtocolDisabled(protocol);
    }
}

// Version-specific adapter interface
interface ISwapAdapter {
    function executeSwap(
        address router,
        address token,
        uint256 amount,
        address recipient
    ) external;
}

interface IVersioned {
    function version() external view returns (uint256);
}
