// SECURE - Efficient caching implementation
contract EfficientContract {
    struct CachedData {
        uint256 baseRate;
        uint256 userMultiplier;
        uint256 timeBonus;
        uint256 lastUpdate;
        bool isValid;
    }

    mapping(address => CachedData) private cache;
    uint256 private constant CACHE_DURATION = 1 hours;

    function calculateRewards(address user, uint256 period) external returns (uint256) {
        _updateCache(user, period);
        CachedData storage data = cache[user];

        return data.baseRate * data.userMultiplier * data.timeBonus / 1e18;
    }

    function calculateFees(address user, uint256 period) external returns (uint256) {
        _updateCache(user, period);
        CachedData storage data = cache[user];

        return data.baseRate * data.userMultiplier / 100;
    }

    function _updateCache(address user, uint256 period) private {
        CachedData storage data = cache[user];

        if (!data.isValid || block.timestamp - data.lastUpdate > CACHE_DURATION) {
            data.baseRate = getBaseRate();
            data.userMultiplier = getUserMultiplier(user);
            data.timeBonus = getTimeBonus(period);
            data.lastUpdate = block.timestamp;
            data.isValid = true;
        }
    }
}
