contract EfficientContract {
    struct BatchTransfer {
        address to;
        uint256 amount;
    }

    function batchTransfer(BatchTransfer[] calldata transfers) external {
        require(transfers.length <= MAX_BATCH_SIZE, "Batch too large");

        uint256 totalAmount = 0;

        // Pre-calculate total to check balance once
        for (uint256 i = 0; i < transfers.length; i++) {
            totalAmount += transfers[i].amount;
        }

        require(balanceOf[msg.sender] >= totalAmount, "Insufficient balance");

        // Execute all transfers
        for (uint256 i = 0; i < transfers.length; i++) {
            _transfer(msg.sender, transfers[i].to, transfers[i].amount);
        }

        emit BatchTransferCompleted(msg.sender, transfers.length, totalAmount);
    }

    uint256 private constant MAX_BATCH_SIZE = 100;
}
