// SECURE - Comprehensive input sanitization
contract SecureContract {
    mapping(string => uint256) public data;

    uint256 private constant MAX_KEY_LENGTH = 64;
    uint256 private constant MAX_VALUE = 1e30;

    function setData(string memory key, uint256 value) external {
        require(_isValidKey(key), "Invalid key format");
        require(value <= MAX_VALUE, "Value too large");
        require(value > 0, "Value must be positive");

        data[key] = value;
    }

    function _isValidKey(string memory key) private pure returns (bool) {
        bytes memory keyBytes = bytes(key);

        if (keyBytes.length == 0 || keyBytes.length > MAX_KEY_LENGTH) {
            return false;
        }

        for (uint256 i = 0; i < keyBytes.length; i++) {
            bytes1 char = keyBytes[i];
            if (!(char >= 0x30 && char <= 0x39) && // 0-9
                !(char >= 0x41 && char <= 0x5A) && // A-Z
                !(char >= 0x61 && char <= 0x7A) && // a-z
                char != 0x5F) { // underscore
                return false;
            }
        }

        return true;
    }
}
